//! tonic gRPC handler for sales (Go `handler/grpc.go`
//! parity, port-spec §5.3a). Maps `proto/sales/v1/sales.proto` payloads
//! to/from the feature's contract types and calls `usecase::Service` —
//! never domain entities.
//!
//! Proto module generated by `build.rs` into `OUT_DIR`. With package
//! `sales.v1` and no `rust_package` override, `tonic::include_proto!` emits a
//! module named after the package with dots replaced by underscores:
//! `sales_v1`.
//!
//! May reference only the usecase service and contract
//! (`tests/architecture.rs`: handler-ignores-repository).

use std::sync::Arc;

use tonic::{Request, Response, Status};

use crate::features::sales::contract::{PurchaseRequest, PurchaseResponse};
use crate::features::sales::usecase::Service;
use crate::platform::errors::AppError;
use crate::platform::server::GRPC_MESSAGE_SIZE_LIMIT;

pub mod sales_v1 {
    // tonic's generated server trait boxes its futures and the `async_trait`
    // expansion adds a message-less `#[must_use]`, which trips
    // `clippy::double_must_use` on generated code we do not own.
    #![allow(clippy::double_must_use)]

    tonic::include_proto!("sales.v1");
}

use sales_v1::{
    PurchaseRequest as PbPurchaseRequest, PurchaseResponse as PbPurchaseResponse,
    sales_service_server::{SalesService, SalesServiceServer},
};

/// tonic server implementation for the sales feature. Generic over the inbound
/// port so tests inject a `MockService` and `di` wires `Arc<dyn Service>`.
pub struct GrpcServer<S: Service + ?Sized> {
    service: Arc<S>,
}

// Manual Clone impl: `Arc<S>` is `Clone` for any `S`, including `?Sized`.
impl<S: Service + ?Sized> Clone for GrpcServer<S> {
    fn clone(&self) -> Self {
        Self {
            service: self.service.clone(),
        }
    }
}

impl<S: Service + ?Sized + 'static> GrpcServer<S> {
    pub fn new(service: Arc<S>) -> Self {
        Self { service }
    }
}

#[tonic::async_trait]
impl<S: Service + ?Sized + 'static> SalesService for GrpcServer<S> {
    async fn purchase(
        &self,
        request: Request<PbPurchaseRequest>,
    ) -> Result<Response<PbPurchaseResponse>, Status> {
        let req = request.into_inner();
        let resp = self
            .service
            .purchase(PurchaseRequest {
                machine_id: req.machine_id,
                product_id: req.product_id,
                coins: req.coins,
            })
            .await
            .map_err(|e| AppError::from(e).to_grpc_status())?;
        Ok(Response::new(contract_to_pb(resp)))
    }
}

/// Build the tonic service with the feature's message-size caps applied.
pub fn server<S>(srv: GrpcServer<S>) -> SalesServiceServer<GrpcServer<S>>
where
    S: Service + ?Sized + 'static,
{
    SalesServiceServer::new(srv)
        .max_decoding_message_size(GRPC_MESSAGE_SIZE_LIMIT)
        .max_encoding_message_size(GRPC_MESSAGE_SIZE_LIMIT)
}

fn contract_to_pb(resp: PurchaseResponse) -> PbPurchaseResponse {
    PbPurchaseResponse {
        id: resp.id,
        machine_id: resp.machine_id,
        product_id: resp.product_id,
        price_cents: resp.price_cents,
        total_inserted_cents: resp.total_inserted_cents,
        change_cents: resp.change_cents,
        change_coins: resp.change_coins,
        purchased_at: resp.purchased_at,
    }
}

